              type="email"
              placeholder="colleague@company.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  addInvite();
                }
              }}
            />
            <Button
              variant="primary"
              size="sm"
              onClick={addInvite}
              className="shrink-0"
            >
              <PlusIcon className="size-4" />
            </Button>
          </div>
        </div>

        {invites.length > 0 && (
          <div className="mb-10 flex flex-wrap gap-2 lg:mb-16">
            {invites.map((inv) => (
              <Badge key={inv} variant="secondary" className="gap-1 pr-1">
                {inv}
                <button
                  onClick={() => removeInvite(inv)}
                  className="hover:bg-muted rounded p-0.5"
                >
                  <XIcon className="size-3" />
                </button>
              </Badge>
            ))}
          </div>
        )}

        <div className="flex gap-3">
          <Button variant="primary" onClick={onBack} size="lg">
            <ChevronLeftIcon className="size-4" />
            Back
          </Button>
          <Button className="flex-1" size="lg">
            {invites.length > 0
              ? `Finish & Send ${invites.length} Invite${invites.length > 1 ? "s" : ""}`
              : "Finish Setup"}
          </Button>
        </div>
      </div>
    </div>
  );
};

